{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE vahdam_db.maplemonk1.vahdam_us_retail_pnl_fy27 AS ( WITH params AS (SELECT 90.0::FLOAT AS fx_inr), sku_master AS ( SELECT \'USA\' AS geo, \'Walmart\' AS src, TRIM(\"Walmart Offline\",\' \t\r\n\') AS retailer_item, ANY_VALUE(TRIM(\"Common SKU ID\",\' \t\r\n\')) AS common_sku_id, ANY_VALUE(TRIM(\"Common SKU Description\",\' \t\r\n\')) AS common_sku_description, ANY_VALUE(TRIM(BRAND,\' \t\r\n\')) AS brand, ANY_VALUE(TRIM(CATEGORY,\' \t\r\n\')) AS category, ANY_VALUE(TRIM(\"Sub-category\",\' \t\r\n\')) AS sub_category, ANY_VALUE(TRIM(\"Common Name\",\' \t\r\n\')) AS common_name, ANY_VALUE(TRIM(\"Master SKU\",\' \t\r\n\')) AS master_sku, ANY_VALUE(TRIM(\"Type-3\",\' \t\r\n\')) AS type_3, ANY_VALUE(TRIM(FORMAT,\' \t\r\n\')) AS pack_format FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING WHERE NULLIF(TRIM(\"Walmart Offline\",\' \t\r\n\'),\'\') IS NOT NULL GROUP BY 1,2,3 UNION ALL SELECT \'USA\', \'Target\', TRIM(\"Target \",\' \t\r\n\'), ANY_VALUE(TRIM(\"Common SKU ID\",\' \t\r\n\')), ANY_VALUE(TRIM(\"Common SKU Description\",\' \t\r\n\')), ANY_VALUE(TRIM(BRAND,\' \t\r\n\')), ANY_VALUE(TRIM(CATEGORY,\' \t\r\n\')), ANY_VALUE(TRIM(\"Sub-category\",\' \t\r\n\')), ANY_VALUE(TRIM(\"Common Name\",\' \t\r\n\')), ANY_VALUE(TRIM(\"Master SKU\",\' \t\r\n\')), ANY_VALUE(TRIM(\"Type-3\",\' \t\r\n\')), ANY_VALUE(TRIM(FORMAT,\' \t\r\n\')) FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING WHERE NULLIF(TRIM(\"Target \",\' \t\r\n\'),\'\') IS NOT NULL GROUP BY 1,2,3 ), cp_rates AS ( SELECT \'USA\' AS geo, \'Walmart\' AS src, TRIM(\"Walmart Item #\",\' \t\r\n\') AS retailer_item, NULLIF(TRIM(\"Budget Common SKU\",\' \t\r\n\'),\'\') AS budget_sku, NULLIF(TRIM(\"Common SKU (SAP)\",\' \t\r\n\'),\'\') AS sap_sku, NULLIF(TRIM(\"Common SKU (Product Mapping)\",\' \t\r\n\'),\'\') AS pm_sku_cp, NULLIF(TRIM(\"Common SKU Desc (Product Mapping)\",\' \t\r\n\'),\'\') AS sku_description_cp, TRY_TO_NUMBER(TRIM(\"Case Pack\",\' \t\r\n\')) AS case_pack, LOWER(NULLIF(TRIM(\"Budget UOM\",\' \t\r\n\'),\'\')) AS budget_uom, NULLIF(TRIM(\"Made in USA?\",\' \t\r\n\'),\'\') AS made_in_usa, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"ASP per Each (Vahdam to Walmart) $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS asp_per_each_usd, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"POS ASP $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS pos_asp_usd, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted COGS / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS cogs_per_each_usd_cp, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted Outbound / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS outbound_per_each_usd_cp, TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted 3PL + Storage / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) AS three_pl_storage_per_each_usd_cp FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_WALMART_CP___BUDGET UNION ALL SELECT \'USA\', \'Target\', TRIM(\"Target TCIN\",\' \t\r\n\'), NULLIF(TRIM(\"Budget Common SKU\",\' \t\r\n\'),\'\'), NULLIF(TRIM(\"Common SKU (SAP)\",\' \t\r\n\'),\'\'), NULLIF(TRIM(\"Common SKU (Product Mapping)\",\' \t\r\n\'),\'\'), NULLIF(TRIM(\"Common SKU Desc (Product Mapping)\",\' \t\r\n\'),\'\'), TRY_TO_NUMBER(TRIM(\"Case Pack\",\' \t\r\n\')), \'each\', NULLIF(TRIM(\"Made in USA?\",\' \t\r\n\'),\'\'), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"ASP (Vahdam to Target) $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"POS ASP $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted COGS / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted Outbound / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6), TRY_TO_DECIMAL(REPLACE(REPLACE(TRIM(\"Budgeted 3PL + Storage / each $\",\' \t\r\n\'),\'$\',\'\'),\',\',\'\'),30,6) FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_TARGET_CP___BUDGET ), pos_walmart AS ( SELECT TRY_TO_DATE(SPLIT_PART(BUSINESS_DATE,\' \',1),\'YYYY-MM-DD\') AS day, TRIM(WALMART_ITEM_NUMBER,\' \t\r\n\') AS retailer_item, MAX(ITEM_NAME) AS retailer_item_name, SUM(TRY_TO_DECIMAL(REGEXP_REPLACE(POS_QUANTITY_THIS_YEAR::STRING,\'[^0-9.\-]\',\'\'),30,4)) AS pos_units, SUM(TRY_TO_DECIMAL(REGEXP_REPLACE(POS_SALES_THIS_YEAR::STRING ,\'[^0-9.\-]\',\'\'),30,4)) AS pos_retail_usd, COUNT(DISTINCT CASE WHEN TRY_TO_DECIMAL(REGEXP_REPLACE(POS_QUANTITY_THIS_YEAR::STRING,\'[^0-9.\-]\',\'\'),30,4) > 0 THEN STORE_NUMBER END) AS selling_locations FROM vahdam_db.maplemonk1.WALMART_SALES_DATA_WALMART_SALES_DATA_RAW GROUP BY 1,2 ), pos_target AS ( SELECT TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\') AS day, TRIM(\"TCIN\",\' \t\r\n\') AS retailer_item, MAX(TRIM(\"ITEM DESCRIPTION\",\' \t\r\n\')) AS retailer_item_name, SUM(TRY_TO_DECIMAL(REPLACE(\"SALES U\",\',\',\'\'),30,4)) AS pos_units, SUM(TRY_TO_DECIMAL(REPLACE(REPLACE(\"SALES $\",\'$\',\'\'),\',\',\'\'),30,4)) AS pos_retail_usd, COUNT(DISTINCT CASE WHEN TRY_TO_DECIMAL(REPLACE(\"SALES U\",\',\',\'\'),30,4) > 0 THEN TRIM(\"LOCATION ID\",\' \t\r\n\') END) AS selling_locations FROM vahdam_db.maplemonk1.TARGET_SALES_TARGET_SALES GROUP BY 1,2 ), pos_all AS ( SELECT \'USA\' AS geo, \'Walmart\' AS src, day, retailer_item, retailer_item_name, pos_units, pos_retail_usd, selling_locations FROM pos_walmart WHERE day IS NOT NULL UNION ALL SELECT \'USA\', \'Target\', day, retailer_item, retailer_item_name, pos_units, pos_retail_usd, selling_locations FROM pos_target WHERE day IS NOT NULL ), actuals AS ( SELECT p.day, p.geo, p.src, p.retailer_item, p.retailer_item_name, CASE WHEN p.src = \'Target\' THEN \'Target\' WHEN COALESCE(m.common_sku_id, c.sap_sku) IN (\'TB024003369-GT\',\'TB024003368-BT\',\'LF060003372-CT\',\'LF060003371-BT\') THEN \'Private Label\' ELSE \'Walmart\' END AS channel, COALESCE(m.common_sku_id, c.pm_sku_cp, c.sap_sku, c.budget_sku) AS common_sku_id, COALESCE(m.common_sku_description, c.sku_description_cp) AS common_sku_description, c.budget_sku, c.sap_sku, c.pm_sku_cp AS pm_sku, m.brand, m.category, m.sub_category, m.common_name, m.master_sku, m.type_3, m.pack_format, COALESCE(c.case_pack,1) AS case_pack, c.budget_uom, c.made_in_usa, c.asp_per_each_usd, c.pos_asp_usd, c.cogs_per_each_usd_cp, c.outbound_per_each_usd_cp, c.three_pl_storage_per_each_usd_cp, DATE_TRUNC(\'MONTH\', p.day) AS month_start, p.pos_units AS qty_actual_eaches, p.pos_retail_usd AS pos_retail_sales_usd, p.selling_locations, p.pos_units * c.asp_per_each_usd AS net_sales_actual_usd, CASE WHEN m.retailer_item IS NULL THEN \'UNMAPPED\' WHEN c.retailer_item IS NULL THEN \'MAPPED_NO_RATES\' WHEN c.asp_per_each_usd IS NULL THEN \'MAPPED_NO_ASP\' ELSE \'OK\' END AS sku_setup_status FROM pos_all p LEFT JOIN sku_master m ON m.retailer_item = p.retailer_item AND m.geo = p.geo AND m.src = p.src LEFT JOIN cp_rates c ON c.retailer_item = p.retailer_item AND c.geo = p.geo AND c.src = p.src ), budget_raw AS ( SELECT TRIM(b.\"Common SKU\",\' \t\r\n\') AS budget_sku, b.\"Platform\" AS channel, UPPER(b.\"Geography\") AS geo, b.\"MONTH_DT\" AS month_start, COALESCE(d.case_pack,1) AS case_pack, CASE WHEN LOWER(COALESCE(d.budget_uom,\'each\')) = \'case\' AND COALESCE(d.case_pack,1) > 1 THEN d.case_pack ELSE 1 END AS uom_factor, SUM(b.\"Qty\") AS qty_budget_uom, SUM(b.\"Net Sales\") AS net_sales_budget_inr, SUM(b.\"COGS\") AS cogs_budget_inr, SUM(b.\"TP Value\") AS tp_budget_inr, SUM(b.\"Add Tariff\") AS tariff_budget_inr, SUM(b.\"Commission\") AS commission_budget_inr, SUM(b.\"Outbound\") AS outbound_budget_inr, SUM(b.\"3PL + Storage\") AS three_pl_storage_budget_inr, SUM(b.\"Last mile\") AS last_mile_budget_inr, SUM(b.\"Payment Commission\") AS payment_commission_budget_inr, SUM(b.\"Performance Marketing\") AS pm_budget_inr, SUM(b.\"Cost of Offline Sales\") AS coos_budget_inr FROM vahdam_db.maplemonk1.OFFLINE_BUDGET_FY27 b LEFT JOIN (SELECT budget_sku, ANY_VALUE(case_pack) case_pack, ANY_VALUE(budget_uom) budget_uom FROM cp_rates WHERE budget_sku IS NOT NULL GROUP BY 1) d ON d.budget_sku = TRIM(b.\"Common SKU\",\' \t\r\n\') WHERE b.\"Platform\" IN (\'Walmart\',\'Target\',\'Private Label\') AND UPPER(b.\"Geography\") = \'USA\' AND NULLIF(TRIM(b.\"Common SKU\",\' \t\r\n\'),\'\') IS NOT NULL GROUP BY 1,2,3,4,5,6 ), budget_rates AS ( SELECT budget_sku, channel, geo, month_start, case_pack, qty_budget_uom * uom_factor AS qty_budget_eaches, net_sales_budget_inr, cogs_budget_inr, tp_budget_inr, tariff_budget_inr, commission_budget_inr, outbound_budget_inr, three_pl_storage_budget_inr, last_mile_budget_inr, payment_commission_budget_inr, pm_budget_inr, coos_budget_inr, DIV0(cogs_budget_inr , qty_budget_uom * uom_factor) AS cogs_per_each_inr, DIV0(tp_budget_inr , qty_budget_uom * uom_factor) AS tp_per_each_inr, DIV0(tariff_budget_inr , qty_budget_uom * uom_factor) AS tariff_per_each_inr, DIV0(outbound_budget_inr , qty_budget_uom * uom_factor) AS outbound_per_each_inr, DIV0(three_pl_storage_budget_inr , qty_budget_uom * uom_factor) AS three_pl_storage_per_each_inr, DIV0(last_mile_budget_inr , qty_budget_uom * uom_factor) AS last_mile_per_each_inr, DIV0(commission_budget_inr , net_sales_budget_inr) AS commission_pct_budget, DIV0(payment_commission_budget_inr , net_sales_budget_inr) AS payment_commission_pct_budget FROM budget_raw ), budget_rates_sku AS ( SELECT budget_sku, channel, geo, AVG(cogs_per_each_inr) AS cogs_per_each_inr_avg, AVG(tp_per_each_inr) AS tp_per_each_inr_avg, AVG(tariff_per_each_inr) AS tariff_per_each_inr_avg, AVG(outbound_per_each_inr) AS outbound_per_each_inr_avg, AVG(three_pl_storage_per_each_inr) AS three_pl_storage_per_each_inr_avg, AVG(last_mile_per_each_inr) AS last_mile_per_each_inr_avg, AVG(commission_pct_budget) AS commission_pct_avg, AVG(payment_commission_pct_budget) AS payment_commission_pct_avg FROM budget_rates GROUP BY 1,2,3 ), commission_driver AS ( SELECT TRIM(\"CHANNEL\",\' \t\r\n\') AS channel, TRY_TO_DECIMAL(REPLACE(TRIM(\"Budget Commission %\",\' \t\r\n\'),\'%\',\'\'),30,6)/100 AS commission_pct_driver FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_OFFLINE_COMMISSION ), coos_driver AS ( SELECT CASE WHEN TRIM(\"CHANNEL\",\' \t\r\n\') = \'PrivateLabel\' THEN \'Private Label\' ELSE TRIM(\"CHANNEL\",\' \t\r\n\') END AS channel, SUM(TRY_TO_DECIMAL(REPLACE(TRIM(\"Budget%\",\' \t\r\n\'),\'%\',\'\'),30,6)/100) AS coos_pct_driver FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_OFFLINE_COOS WHERE UPPER(TRIM(\"GEO\",\' \t\r\n\')) = \'USA\' GROUP BY 1 ), other_coos_raw AS ( SELECT TRIM(\"CHARGE\",\' \t\r\n\') AS charge, mth, TRY_TO_DECIMAL(REPLACE(val,\',\',\'\'),30,4) AS amt_inr FROM vahdam_db.maplemonk1.VAHDAM_FY27_INPUTS_OFFLINE_OTHER_COOS UNPIVOT INCLUDE NULLS (val FOR mth IN (\"April-2026\",\"May-2026\",\"June-2026\",\"July-2026\",\"August-2026\", \"September-2026\",\"October-2026\",\"November-2026\",\"December-2026\", \"January-2027\",\"February-2027\",\"March-2027\")) ), other_coos_month AS ( SELECT charge, TO_DATE(\'01-\'||REPLACE(mth,\'-\',\' -\'), \'DD-MMMM -YYYY\') AS month_start, amt_inr FROM other_coos_raw ), other_coos_filled AS ( SELECT charge, month_start, amt_inr AS amt_reported, COALESCE( amt_inr, AVG(amt_inr) OVER (PARTITION BY charge ORDER BY month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) ) AS amt_used_inr FROM other_coos_month ), other_coos_total AS ( SELECT month_start, SUM(amt_used_inr) AS other_coos_total_inr FROM other_coos_filled GROUP BY 1 ), pm_walmart AS ( SELECT DATE_TRUNC(\'MONTH\',\"c_DATE\") AS month_start, SUM(TRY_TO_DOUBLE(\"ADSPEND_ST\")) AS spend_usd FROM (SELECT \"c_DATE\",\"ADSPEND_ST\", ROW_NUMBER() OVER (PARTITION BY CAMPAIGNID_ST, ADGROUPID_ST, \"c_DATE\" ORDER BY DATON_BATCH_RUNTIME DESC NULLS LAST) rn FROM DATON.RAW.WALMART_CONNECT_US_1P_ADGROUPSNAPSHOTREPORT) WHERE rn = 1 GROUP BY 1 ), pm_target AS ( SELECT DATE_TRUNC(\'MONTH\', TRY_TO_DATE(SPLIT_PART(\"Event Date\",\' \',1),\'DD-MM-YYYY\')) AS month_start, SUM(TRY_TO_DOUBLE(REPLACE(REPLACE(\"Actualized Vendor Spend\",\'$\',\'\'),\',\',\'\'))) AS spend_usd FROM vahdam_db.maplemonk1.TARGET_ADS_DAY_TARGET_ADS_REPORT GROUP BY 1 ), cashback_ibotta AS ( SELECT DATE_TRUNC(\'MONTH\', TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\')) AS month_start, SUM(TRY_TO_DOUBLE(REPLACE(REPLACE(\"Total Spend ($)\",\'$\',\'\'),\',\',\'\'))) AS spend_usd FROM vahdam_db.maplemonk1.TARGET_IBOTTA_REPORT_TARGET_IBOTTA_REPORT GROUP BY 1 ), aisle_src AS ( SELECT COALESCE(TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'YYYY-MM-DD\')) AS day, (CASE WHEN \"Fees ($)\" LIKE \'(%\' THEN -1 ELSE 1 END * TRY_TO_DOUBLE(REPLACE(REPLACE(REPLACE(REPLACE(\"Fees ($)\" ,\'(\',\'\'),\')\',\'\'),\'$\',\'\'),\',\',\'\'))) AS fees, (CASE WHEN \"Payout ($)\" LIKE \'(%\' THEN -1 ELSE 1 END * TRY_TO_DOUBLE(REPLACE(REPLACE(REPLACE(REPLACE(\"Payout ($)\",\'(\',\'\'),\')\',\'\'),\'$\',\'\'),\',\',\'\'))) AS payout, ROW_NUMBER() OVER (PARTITION BY COALESCE(TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'DD-MM-YYYY\'), TRY_TO_DATE(SPLIT_PART(\"DATE\",\' \',1),\'YYYY-MM-DD\')), \"CAMPAIGN\" ORDER BY \"_AB_SOURCE_FILE_LAST_MODIFIED\" DESC NULLS LAST) rn FROM vahdam_db.maplemonk1.TARGET_AISLE_TARGET_AISLE_REPORT ), cashback_aisle AS ( SELECT DATE_TRUNC(\'MONTH\',day) AS month_start, SUM(COALESCE(fees,0)+COALESCE(payout,0)) AS spend_usd FROM aisle_src WHERE rn = 1 AND day IS NOT NULL GROUP BY 1 ), spend_by_channel_month AS ( SELECT \'Walmart\' AS channel, month_start, spend_usd AS pm_spend_usd, 0 AS cashback_spend_usd FROM pm_walmart UNION ALL SELECT \'Target\', COALESCE(t.month_start,i.month_start,a.month_start), COALESCE(t.spend_usd,0), COALESCE(i.spend_usd,0) + COALESCE(a.spend_usd,0) FROM pm_target t FULL JOIN cashback_ibotta i ON i.month_start = t.month_start FULL JOIN cashback_aisle a ON a.month_start = COALESCE(t.month_start,i.month_start) ), sales_channel_month AS ( SELECT channel, geo, month_start, SUM(net_sales_actual_usd) AS ch_sales_usd FROM actuals GROUP BY 1,2,3 ), sales_all_month AS ( SELECT month_start, SUM(net_sales_actual_usd) AS all_sales_usd FROM actuals GROUP BY 1 ), joined AS ( SELECT a.day, a.month_start, a.channel, a.geo, a.retailer_item, a.retailer_item_name, a.common_sku_id, a.common_sku_description, a.budget_sku, a.sap_sku, a.pm_sku, a.sku_setup_status, a.case_pack, a.budget_uom, a.made_in_usa, a.selling_locations, a.brand, a.category, a.sub_category, a.common_name, a.master_sku, a.type_3, a.pack_format, p.fx_inr, a.qty_actual_eaches, a.asp_per_each_usd, a.pos_asp_usd, a.pos_retail_sales_usd, a.net_sales_actual_usd, COALESCE(a.cogs_per_each_usd_cp * p.fx_inr, br.cogs_per_each_inr, brs.cogs_per_each_inr_avg) AS cogs_per_each_inr, COALESCE(br.tp_per_each_inr , brs.tp_per_each_inr_avg) AS tp_per_each_inr, COALESCE(br.tariff_per_each_inr , brs.tariff_per_each_inr_avg) AS tariff_per_each_inr, COALESCE(a.outbound_per_each_usd_cp * p.fx_inr, br.outbound_per_each_inr, brs.outbound_per_each_inr_avg) AS outbound_per_each_inr, COALESCE(a.three_pl_storage_per_each_usd_cp * p.fx_inr, br.three_pl_storage_per_each_inr, brs.three_pl_storage_per_each_inr_avg) AS three_pl_storage_per_each_inr, COALESCE(br.last_mile_per_each_inr , brs.last_mile_per_each_inr_avg) AS last_mile_per_each_inr, COALESCE(cd.commission_pct_driver, br.commission_pct_budget, brs.commission_pct_avg) AS commission_pct, COALESCE(br.payment_commission_pct_budget, brs.payment_commission_pct_avg) AS payment_commission_pct, COALESCE(cod.coos_pct_driver, 0) AS coos_pct, DIV0(a.net_sales_actual_usd, scm.ch_sales_usd) AS share_of_channel_month, DIV0(a.net_sales_actual_usd, sam.all_sales_usd) AS share_of_all_month, COALESCE(sp.pm_spend_usd,0) * DIV0(a.net_sales_actual_usd, scm.ch_sales_usd) AS pm_spend_actual_usd, COALESCE(sp.cashback_spend_usd,0) * DIV0(a.net_sales_actual_usd, scm.ch_sales_usd) AS cashback_spend_actual_usd, COALESCE(oct.other_coos_total_inr,0) * DIV0(a.net_sales_actual_usd, sam.all_sales_usd) AS other_coos_inr, CASE WHEN br.budget_sku IS NOT NULL THEN \'N\' WHEN brs.budget_sku IS NOT NULL THEN \'Y\' ELSE \'NO_BUDGET\' END AS cost_rate_carried_forward, CASE WHEN a.cogs_per_each_usd_cp IS NOT NULL THEN \'CP_INPUT_TABLE\' WHEN br.cogs_per_each_inr IS NOT NULL THEN \'BUDGET_DERIVED\' WHEN brs.cogs_per_each_inr_avg IS NOT NULL THEN \'BUDGET_SKU_AVG\' ELSE \'NONE\' END AS cogs_rate_source, CASE WHEN a.outbound_per_each_usd_cp IS NOT NULL THEN \'CP_INPUT_TABLE\' WHEN br.outbound_per_each_inr IS NOT NULL THEN \'BUDGET_DERIVED\' WHEN brs.outbound_per_each_inr_avg IS NOT NULL THEN \'BUDGET_SKU_AVG\' ELSE \'NONE\' END AS outbound_rate_source, CASE WHEN a.three_pl_storage_per_each_usd_cp IS NOT NULL THEN \'CP_INPUT_TABLE\' WHEN br.three_pl_storage_per_each_inr IS NOT NULL THEN \'BUDGET_DERIVED\' WHEN brs.three_pl_storage_per_each_inr_avg IS NOT NULL THEN \'BUDGET_SKU_AVG\' ELSE \'NONE\' END AS three_pl_storage_rate_source, br.qty_budget_eaches, br.net_sales_budget_inr, br.cogs_budget_inr, br.tp_budget_inr, br.tariff_budget_inr, br.commission_budget_inr, br.outbound_budget_inr, br.three_pl_storage_budget_inr, br.last_mile_budget_inr, br.payment_commission_budget_inr, br.pm_budget_inr, br.coos_budget_inr FROM actuals a CROSS JOIN params p LEFT JOIN budget_rates br ON br.budget_sku = a.budget_sku AND br.channel = a.channel AND br.geo = a.geo AND br.month_start = a.month_start LEFT JOIN budget_rates_sku brs ON brs.budget_sku = a.budget_sku AND brs.channel = a.channel AND brs.geo = a.geo LEFT JOIN commission_driver cd ON cd.channel = a.channel LEFT JOIN coos_driver cod ON cod.channel = a.channel LEFT JOIN sales_channel_month scm ON scm.channel = a.channel AND scm.geo = a.geo AND scm.month_start = a.month_start LEFT JOIN sales_all_month sam ON sam.month_start = a.month_start LEFT JOIN spend_by_channel_month sp ON sp.channel = a.channel AND sp.month_start = a.month_start LEFT JOIN other_coos_total oct ON oct.month_start = a.month_start ) SELECT day, month_start, CASE WHEN day >= \'2026-04-01\' AND day <= \'2027-03-31\' THEN \'FY27\' WHEN day >= \'2025-04-01\' AND day <= \'2026-03-31\' THEN \'FY26\' ELSE 