nr IS NOT NULL AND outbound_per_each_inr IS NOT NULL AND three_pl_storage_per_each_inr IS NOT NULL AND commission_pct IS NOT NULL THEN \'COMPLETE\' ELSE \'PARTIAL\' END AS cost_completeness FROM joined );",
